BEGIN;
CREATE TABLE hr_goals(id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,company_id TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,branch_id TEXT REFERENCES branches(id) ON DELETE CASCADE,staff_id TEXT REFERENCES staff(id) ON DELETE CASCADE,team_id TEXT REFERENCES hr_teams(id) ON DELETE CASCADE,position_id TEXT REFERENCES hr_positions(id) ON DELETE CASCADE,name TEXT NOT NULL,metric_key TEXT NOT NULL,target_value DECIMAL(16,4) NOT NULL,actual_value DECIMAL(16,4) NOT NULL DEFAULT 0,unit TEXT,weight DECIMAL(6,3) NOT NULL DEFAULT 1,stretch_target DECIMAL(16,4),period_type TEXT NOT NULL CHECK(period_type IN('MONTHLY','QUARTERLY','ANNUAL','CUSTOM')),starts_on DATE NOT NULL,ends_on DATE NOT NULL,status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(status IN('DRAFT','ACTIVE','COMPLETED','CANCELLED')),created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK(ends_on>=starts_on));
CREATE INDEX hr_goals_scope_idx ON hr_goals(tenant_id,company_id,branch_id,staff_id,status);
CREATE TABLE hr_performance_review_cycles(id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,company_id TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,name TEXT NOT NULL,starts_on DATE NOT NULL,ends_on DATE NOT NULL,status TEXT NOT NULL DEFAULT 'DRAFT' CHECK(status IN('DRAFT','OPEN','CALIBRATION','CLOSED')),created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK(ends_on>=starts_on));
CREATE TABLE hr_performance_reviews(id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,company_id TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,branch_id TEXT NOT NULL REFERENCES branches(id) ON DELETE RESTRICT,cycle_id TEXT NOT NULL REFERENCES hr_performance_review_cycles(id) ON DELETE CASCADE,staff_id TEXT NOT NULL REFERENCES staff(id) ON DELETE CASCADE,manager_staff_id TEXT REFERENCES staff(id) ON DELETE SET NULL,self_score DECIMAL(6,2),manager_score DECIMAL(6,2),final_score DECIMAL(6,2),achievements TEXT,development_areas TEXT,development_plan TEXT,status TEXT NOT NULL DEFAULT 'PENDING_SELF' CHECK(status IN('PENDING_SELF','PENDING_MANAGER','CALIBRATION','FINALIZED')),created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(cycle_id,staff_id));
CREATE TABLE hr_career_paths(id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,company_id TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,from_position_id TEXT NOT NULL REFERENCES hr_positions(id) ON DELETE CASCADE,to_position_id TEXT NOT NULL REFERENCES hr_positions(id) ON DELETE CASCADE,min_experience_months INTEGER NOT NULL DEFAULT 0,required_competencies JSONB NOT NULL DEFAULT '[]'::jsonb,required_certifications JSONB NOT NULL DEFAULT '[]'::jsonb,active BOOLEAN NOT NULL DEFAULT TRUE,UNIQUE(tenant_id,company_id,from_position_id,to_position_id));
CREATE TABLE hr_succession_candidates(id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,company_id TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,critical_position_id TEXT NOT NULL REFERENCES hr_positions(id) ON DELETE CASCADE,staff_id TEXT NOT NULL REFERENCES staff(id) ON DELETE CASCADE,readiness TEXT NOT NULL CHECK(readiness IN('READY_NOW','LT_1_YEAR','ONE_TO_TWO_YEARS','LONG_TERM')),risk TEXT CHECK(risk IN('LOW','MEDIUM','HIGH')),development_gaps TEXT,target_readiness_date DATE,created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(tenant_id,critical_position_id,staff_id));
CREATE TABLE hr_recognitions(id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,company_id TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,branch_id TEXT NOT NULL REFERENCES branches(id) ON DELETE RESTRICT,staff_id TEXT NOT NULL REFERENCES staff(id) ON DELETE CASCADE,source TEXT NOT NULL,title TEXT NOT NULL,message TEXT,points INTEGER NOT NULL DEFAULT 0,reward_earning_id TEXT REFERENCES hr_variable_earnings(id) ON DELETE SET NULL,recognized_by TEXT,created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE hr_employee_cases(id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,company_id TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,branch_id TEXT NOT NULL REFERENCES branches(id) ON DELETE RESTRICT,staff_id TEXT REFERENCES staff(id) ON DELETE SET NULL,case_type TEXT NOT NULL,title TEXT NOT NULL,description TEXT,status TEXT NOT NULL DEFAULT 'OPEN' CHECK(status IN('OPEN','IN_REVIEW','ACTION_REQUIRED','RESOLVED','CLOSED')),severity TEXT NOT NULL DEFAULT 'NORMAL' CHECK(severity IN('LOW','NORMAL','HIGH','CRITICAL')),owner_id TEXT,restricted BOOLEAN NOT NULL DEFAULT TRUE,resolution TEXT,created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,closed_at TIMESTAMP(3));
CREATE INDEX hr_employee_cases_queue_idx ON hr_employee_cases(tenant_id,company_id,status,severity,created_at);
CREATE TABLE hr_employee_relations_actions(id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,case_id TEXT NOT NULL REFERENCES hr_employee_cases(id) ON DELETE CASCADE,action_type TEXT NOT NULL CHECK(action_type IN('INCIDENT','EXPLANATION_REQUEST','WARNING','DECISION','CORRECTIVE_ACTION','NOTE')),description TEXT NOT NULL,effective_date DATE,created_by TEXT,created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
COMMIT;
